ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS ndpa_consent BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN IF NOT EXISTS ndpa_consent_at TIMESTAMPTZ, ADD COLUMN IF NOT EXISTS marketing_opt_in BOOLEAN NOT NULL DEFAULT FALSE; COMMENT ON COLUMN public.profiles.ndpa_consent IS 'Explicit affirmative consent to HousePlug Terms of Service and Privacy Policy under NDPA 2023.'; COMMENT ON COLUMN public.profiles.ndpa_consent_at IS 'Timestamp of when explicit legal consent was granted.'; COMMENT ON COLUMN public.profiles.marketing_opt_in IS 'Optional opt-in for email broadcasts, campus updates, and price drop notifications.';